-- ------------------------------------------------------------------
-- Export OS - 00023: HSN / SAC codes directory
--
-- Official CBIC GST HSN/SAC nomenclature. Goods + services codes with
-- chapter grouping, wiring, and pg_trgm indexes for fast product search.
-- Grants public SELECT so exporters can look up codes without a login.
-- ------------------------------------------------------------------

create table if not exists public.hsn_codes (
  code text primary key,
  description text not null,
  code_type text not null check (code_type in ('hsn', 'sac')),
  chapter text,
  created_at timestamptz not null default now()
);

create index if not exists idx_hsn_codes_chapter on public.hsn_codes (chapter);
create index if not exists idx_hsn_codes_type on public.hsn_codes (code_type);
create index if not exists idx_hsn_codes_desc_trgm on public.hsn_codes using gin (description gin_trgm_ops);
create index if not exists idx_hsn_codes_code_trgm on public.hsn_codes using gin (code gin_trgm_ops);

alter table public.hsn_codes enable row level security;

drop policy if exists hsn_select_public on public.hsn_codes;
create policy hsn_select_public on public.hsn_codes for select using (true);

grant select on public.hsn_codes to anon, authenticated;
grant select on public.hsn_codes to service_role;
grant insert, update, delete on public.hsn_codes to service_role;

-- Fast typo-tolerant search: exact/code-prefix first, then trigram similarity.
create or replace function public.search_hsn(
  p_query text,
  p_limit int default 20
)
returns table (code text, description text, code_type text, chapter text, rank float)
language sql
stable
set search_path = public
as $$
  select
    code,
    description,
    code_type,
    chapter,
    case
      when code = upper(p_query) then 0.0
      when code like upper(trim(p_query)) || '%' then 1.0
      else similarity(description, lower(p_query))
    end as rank
  from public.hsn_codes
  where
    code ilike '%' || trim(p_query) || '%'
    or description ilike '%' || trim(p_query) || '%'
  order by rank asc, code
  limit p_limit;
$$;

grant execute on function public.search_hsn(text, int) to anon, authenticated, service_role;

